async def call_exa_search(query: str, num_results: int = 100) -> List[Dict]:
    """Exa AI - Autonomous web search"""
    if not EXA_API_KEY:
        return [{"error": "Exa API key not configured"}]

    try:
        async with aiohttp.ClientSession() as session:
            headers = {
                "x-api-key": EXA_API_KEY,
                "Content-Type": "application/json"
            }
            payload = {
                "query": query,
                "numResults": num_results,
                "type": "auto",
                "contents": {"text": True, "highlights": True}
            }
            async with session.post("", headers=headers, json=payload, timeout=6) as resp:
                if resp.status != 200:
                    text = await resp.text()
                    return [{"error": f"Exa API error: {resp.status} - {text}"}]
                data = await resp.json()
                return data.get("results", [])
    except Exception as e:
        return [{"error": f"Exa error: {str(e)}"}]

async def agent_brain_decide_action(topic: str, current_state: Dict) -> Dict:
    """Claude Sonnet 4.5 decides the next autonomous action"""
    system_prompt = """You are the orchestrating brain of an autonomous DeepSearch AI research agent.
Your role is to strategically plan and decide the next action for comprehensive research.

Available actions:
1. SEARCH - Gather more sources on a specific aspect
2. ANALYZE - Deep analysis of collected content
3. REASON - Logical inference and hypothesis testing
4. SYNTHESIZE - Combine findings into coherent conclusions
5. REPORT - Generate final comprehensive report

You must output a JSON object with this structure:
{
  "action": "SEARCH|ANALYZE|REASON|SYNTHESIZE|REPORT",
  "parameters": {
    "query": "specific search query or analysis focus",
    "reason": "why this action is needed now"
  }
}"""

    prompt = f"""Current research topic: {topic}

Current state:
- Sources collected: {len(current_state.get('sources', []))}
- Insights generated: {len(current_state.get('insights', []))}
- Reasoning steps: {len(current_state.get('reasoning', []))}
- Actions taken: {len(current_state.get('agent_log', []))}

Recent actions:
{json.dumps(current_state.get('agent_log', [])[-5:], indent=2)}

Latest insights:
{json.dumps(current_state.get('insights', [])[-3:], indent=2) if current_state.get('insights') else 'None yet'}

Decide the next optimal action to advance this research comprehensively.
Output only valid JSON."""

    response = await call_claude(prompt, system_prompt)
    try:
        return json.loads(response)
    except:
        # Fallback decision
        if len(current_state.get('sources', [])) < 30:
            return {"action": "SEARCH", "parameters": {"query": topic, "reason": "Need more sources"}}
        elif len(current_state.get('insights', [])) < 10:
            return {"action": "ANALYZE", "parameters": {"query": topic, "reason": "Need analysis"}}
        else:
            return {"action": "REPORT", "parameters": {"query": topic, "reason": "Ready for report"}}

async def execute_search_action(query: str):
    """Execute search action"""
    log_action(f"SEARCH: Gathering sources for: {query}")
    sources = await call_exa_search(query, num_results=100)

    for source in sources[:100]:
        if 'error' not in source:
            memory["sources"].append({
                "title": source.get("title", "Untitled"),
                "url": source.get("url", ""),
                "text": source.get("text", "")[:5000],
                "highlights": source.get("highlights", [])
            })
    save_memory()
    log_action(f"SEARCH: Collected {len(sources)} new sources")

async def execute_analyze_action(topic: str):
    """Execute analysis action using GPT OSS 120B"""
    log_action("ANALYZE: Deep analysis of collected sources")

    # Analyze top sources
    sources_text = "\n\n".join([
        f"Source: {s.get('title', 'Untitled')}\n{s.get('text', '')[:800]}"
        for s in memory["sources"][-10:]
    ])

    prompt = f"""Analyze these sources about '{topic}' and extract key insights, evidence, and patterns.
Provide structured analysis with specific findings.

Sources:
{sources_text}

Provide detailed analysis."""

    analysis = await call_gpt_oss(prompt)
    if not analysis.startswith("GPT OSS"):
        memory["insights"].append(analysis)
        save_memory()
        log_action("ANALYZE: Generated deep insights")

async def execute_reason_action(topic: str):
    """Execute reasoning action using Grok"""
    log_action("REASON: Logical inference and hypothesis generation")

    insights_text = "\n\n".join(memory["insights"][-5:]) if memory["insights"] else "No insights yet"

    prompt = f"""Based on research about '{topic}', perform logical reasoning:

Current insights:
{insights_text}

Generate:
1. Logical inferences
2. Hypotheses to test
3. Contradictions to resolve
4. Conclusions supported by evidence"""

    reasoning = await call_grok(prompt)
    if not reasoning.startswith("Grok"):
        memory["reasoning"].append(reasoning)
        save_memory()
        log_action("REASON: Generated logical inferences")

async def execute_synthesize_action(topic: str):
    """Execute synthesis using Qwen for structured output"""
    log_action("SYNTHESIZE: Combining findings into structured conclusions")

    all_insights = "\n\n".join(memory["insights"][-10:]) if memory["insights"] else ""
    all_reasoning = "\n\n".join(memory["reasoning"][-5:]) if memory["reasoning"] else ""

    prompt = f"""Synthesize research findings about '{topic}':

Insights:
{all_insights}

Reasoning:
{all_reasoning}

Provide structured synthesis with clear conclusions and evidence."""

    synthesis = await call_qwen(prompt)
    if not synthesis.startswith("Qwen"):
        memory["insights"].append(f"SYNTHESIS: {synthesis}")
        save_memory()
        log_action("SYNTHESIZE: Created structured conclusions")

async def generate_final_report(topic: str):
    """Generate comprehensive HTML report"""
    log_action("REPORT: Generating final comprehensive report")

    # Claude generates report structure
    report_prompt = f"""Generate a comprehensive 20-30 page research report about '{topic}'.

