    with open(REPORT_HTML_FILE, "w", encoding="utf-8") as f:
        f.write(report_html)

    log_action("REPORT: Final report generated successfully")

async def agent_loop(topic: str):
    """Main autonomous agent loop orchestrated by Claude"""
    global research_active, memory
    research_active = True
    load_memory()

    memory = {"sources": [], "insights": [], "reasoning": [], "state": {"topic": topic}, "agent_log": []}
    log_action(f"Starting autonomous research on: {topic}")

    try:
        max_iterations = 15
        iteration = 0

        while iteration < max_iterations and research_active:
            iteration += 1
            log_action(f"Iteration {iteration}/{max_iterations}")

            # Claude decides next action
            decision = await agent_brain_decide_action(topic, memory)
            action = decision.get("action", "SEARCH")
            params = decision.get("parameters", {})

            log_action(f"Decision: {action} - {params.get('reason', '')}")

            # Execute action
            if action == "SEARCH":
                query = params.get("query", topic)
                await execute_search_action(query)

            elif action == "ANALYZE":
                await execute_analyze_action(topic)

            elif action == "REASON":
                await execute_reason_action(topic)

            elif action == "SYNTHESIZE":
                await execute_synthesize_action(topic)

            elif action == "REPORT":
                await generate_final_report(topic)
                memory["state"]["completed"] = True
                save_memory()
                break

            # Small delay between iterations
            await asyncio.sleep(2)

        # Ensure report is generated
        if not memory["state"].get("completed"):
            await generate_final_report(topic)
            memory["state"]["completed"] = True
            save_memory()

    except Exception as e:
        memory["state"]["error"] = str(e)
        save_memory()
        log_action(f"ERROR: {str(e)}")
    finally:
        research_active = False

@app.post("/start")
async def start_research(query: UserQuery):
    global research_active
    if research_active:
        return JSONResponse({"status": "Research already in progress", "topic": query.topic})

    asyncio.create_task(agent_loop(query.topic))
    return JSONResponse({"status": "Research started", "topic": query.topic})

@app.get("/log")
async def get_log():
    load_memory()
    return JSONResponse(memory)

@app.get("/status")
async def get_status():
    return JSONResponse({
        "active": research_active,
        "completed": memory.get("state", {}).get("completed", False),
        "sources_count": len(memory.get("sources", [])),
        "insights_count": len(memory.get("insights", [])),
        "iterations": len(memory.get("agent_log", []))
    })

@app.get("/report")
async def get_report():
    if Path(REPORT_HTML_FILE).exists():
        return FileResponse(REPORT_HTML_FILE, media_type="text/html")
    return JSONResponse({"error": "Report not ready"}, status_code=404)

@app.get("/")
async def serve_index():
    return FileResponse("index.html")

if __name__ == "__main__":
    logger.info("Starting DeepSearch AI Agent...")
    logger.info("Required API Keys: ANTHROPIC_API_KEY, CEREBRAS_API_KEY, XAI_API_KEY, EXA_API_KEY")
    uvicorn.run(app, host="0.0.0.0", port=8080)
